+// Sites: the kitchens Larder serves. Every location belongs to one site and a
+// batch belongs to the site of its location. Items, suppliers, recipes and
+// dishes are shared by all sites (docs/DATA.md).
+import { AppError } from "../errors.js";
+
+/** The site of a request that names none. */
+export const DEFAULT_SITE = "main";
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** Every site, in stored order. */
+export function listSites(store) {
+  return [...(store.data.sites ?? [])];
+}
+
+/** True when `locationId` is a location of `site`. */
+export function inSite(store, locationId, site) {
+  const loc = store.data.locations.find((l) => l.id === locationId);
+  return Boolean(loc) && (loc.site ?? DEFAULT_SITE) === site;
+}
+
+/** Batches kept at the locations of `site` (a batch at an unknown location counts as main). */
+export function siteBatches(store, site) {
+  const siteOf = new Map(store.data.locations.map((l) => [l.id, l.site ?? DEFAULT_SITE]));
+  return store.data.batches.filter((b) => (siteOf.get(b.location) ?? DEFAULT_SITE) === site);
+}
