+test("stock-takes only see their site's locations", async () => {
+  const { handle } = app();
+  const other = await handle({ method: "POST", path: "/stocktakes", headers: annex, body: { location: "dry" } });
+  assert.equal(other.body.error.code, "unknown_location");
+  const take = (await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  const count = await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: annex, body: { batchId: 6, counted: 12 } });
+  assert.equal(count.status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: annex })).status, 404);
+  const own = await handle({ method: "POST", path: "/stocktakes", headers: annex, body: { location: "annex-fridge" } });
+  assert.equal(own.status, 201);
+});
+
+test("the nightly job checks every site", async () => {
+  const { handle, store } = app();
+  await handle({ method: "POST", path: "/jobs/nightly" });
+  const keys = store.data.outbox.map((m) => m.key);
+  assert.ok(keys.includes("expiry:2026-10-28:4"));
+  assert.ok(!keys.includes("low:2026-10-28"));
+  assert.ok(keys.includes("low:annex:2026-10-28"));
+  assert.match(store.data.outbox.find((m) => m.key === "low:annex:2026-10-28").subject, /Annex kitchen/);
+  await handle({ method: "POST", path: "/jobs/nightly", headers: annex });
+  assert.equal(store.data.outbox.length, keys.length);
+});
